// Isolated release-guard regression tests. Never edits the real release.
import assert from 'node:assert/strict';
import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const work=dirname(fileURLToPath(import.meta.url)),repo=join(work,'../ib-maths-expansion');
const guard=await import(pathToFileURL(join(repo,'scripts/verify-ib-physics-mock-reviews.mjs')));
const finalizer=await import(pathToFileURL(join(repo,'scripts/finalize-ib-physics-mock-reviews.mjs')));
const fixture=mkdtempSync(join(work,'guard-mutations-'));
assert.ok(resolve(fixture).startsWith(resolve(work)+'\\') || resolve(fixture).startsWith(resolve(work)+'/'));
for(const file of guard.protectedFilePaths(repo)){const dest=join(fixture,file);mkdirSync(dirname(dest),{recursive:true});cpSync(join(repo,file),dest);}
const before=new Map();
const record=file=>{if(!before.has(file)) before.set(file,existsSync(join(fixture,file))?readFileSync(join(fixture,file)):null);};
const raw=(file,fn)=>{record(file);writeFileSync(join(fixture,file),fn(readFileSync(join(fixture,file))));};
const edit=(file,fn)=>raw(file,b=>{const d=JSON.parse(b);fn(d);return JSON.stringify(d,null,2)+'\n';});
const restore=()=>{for(const [file,b] of before){if(b===null)rmSync(join(fixture,file),{force:true});else writeFileSync(join(fixture,file),b);}before.clear();};
const D='docs/ib-physics-mocks-2026/',C='content/ib/physics-mocks-2026/';
const A=C+'papers/physics-hl-set-a-paper-1.json',S=C+'papers/physics-sl-set-a-paper-2.json';
const I=D+'hl-c-independent-review.json',B=D+'hl-b-independent-review.json';
const results=[];
const mutation=(name,change,validator=()=>guard.readReviewEvidence({root:fixture}))=>{try{change();assert.throws(validator,undefined,name);results.push({name,status:'rejected-as-required'});}finally{restore();}};
try{
  const manifest=finalizer.finalizeReviewManifest(fixture);guard.verifyReviewManifest(fixture);results.push({name:'Complete current evidence and fixture freeze',status:'passed'});
  mutation('Reject superseded SL55 marks',()=>edit(S,d=>d.marks=55));
  mutation('Reject incorrect sitting duration',()=>edit(A,d=>d.minutes=121));
  mutation('Reject missing canonical question',()=>edit(A,d=>d.questions.pop()));
  mutation('Reject wrong MCQ key',()=>edit(A,d=>d.questions[0].correctOption='A'));
  mutation('Reject duplicate physical options',()=>edit(A,d=>d.questions[0].options[1].text=d.questions[0].options[0].text));
  mutation('Reject nonadditive marking points',()=>edit(A,d=>d.questions[40].markScheme[0].steps[0].code='A9'));
  mutation('Reject missing question part',()=>edit(S,d=>d.questions[0].parts.pop()));
  mutation('Reject unsafe scientific SVG',()=>edit(A,d=>d.questions[0].diagramSvg+='<script>alert(1)</script>'));
  mutation('Reject broken table delimiter',()=>edit(C+'papers/physics-hl-set-c-paper-1.json',d=>{d.questions[41].stem=d.questions[41].stem.replace('|---|---:|','|---|---:|---:|');}));
  mutation('Reject unknown syllabus reference',()=>edit(A,d=>d.questions[0].syllabusRefs=['Z.9']));
  mutation('Reject AHL-only content reference in SL',()=>edit(S,d=>d.questions[0].syllabusRefs=['A.5']));
  mutation('Reject impossible source page',()=>edit(A,d=>d.questions[0].sourceAnchors[0].page=999));
  mutation('Reject short repeated answer-key cycle',()=>edit(A,d=>d.questions.slice(0,40).forEach((q,i)=>q.correctOption='ABCD'[i%4])));
  mutation('Reject severe correct-position bias',()=>edit(A,d=>d.questions.slice(0,40).forEach((q,i)=>q.correctOption=i<30?'B':'ACD'[i%3])));
  mutation('Reject empty author calculations',()=>edit(D+'hl-b-author-checks.json',d=>d.checks=[]));
  mutation('Reject stale author paper hash',()=>edit(D+'hl-b-author-checks.json',d=>d.papers[0].sha256='0'.repeat(64)));
  mutation('Reject missing independent question review',()=>edit(I,d=>d.questionReviews.pop()));
  mutation('Reject missing independent written part',()=>edit(I,d=>d.questionReviews[40].parts.pop()));
  mutation('Reject canned independent reasoning',()=>edit(I,d=>d.questionReviews[0].parts[0].reasoning='checked'));
  mutation('Reject duplicated generic part reasoning',()=>edit(I,d=>d.questionReviews[1].parts[0].reasoning=d.questionReviews[0].parts[0].reasoning));
  mutation('Reject false numerical statement',()=>edit(I,d=>{const c=d.checks.find(c=>c.expected!==undefined&&c.expected!==0);c.computed=c.expected*2;}));
  mutation('Reject overly permissive tolerance',()=>edit(I,d=>d.checks[0].absoluteTolerance=1e50));
  mutation('Reject false passed assertion badge',()=>edit(I,d=>d.checks[0].passed=false));
  mutation('Reject stale independently solved option text',()=>edit(I,d=>d.checks.find(c=>c.expectedCorrectText).expectedCorrectText='invented answer'));
  mutation('Reject stale independent paper hash',()=>edit(I,d=>d.papers[0].sha256='f'.repeat(64)));
  mutation('Reject missing native figure review',()=>edit(I,d=>d.figuresReviewed.pop()));
  mutation('Reject different scientifically reviewed SVG',()=>edit(I,d=>d.figuresReviewed[0].svgSha256='0'.repeat(64)));
  mutation('Reject incomplete full-stem review declaration',()=>edit(I,d=>d.questionReviews[0].fullStemAndSchemeRead=false));
  mutation('Reject stale render source',()=>edit(D+'math-assets-checks.json',d=>d.papers[Object.keys(d.papers)[0]]='0'.repeat(64)));
  mutation('Reject changed valid-looking raster evidence',()=>edit(D+'math-assets-checks.json',d=>d.diagrams[Object.keys(d.diagrams)[0]].pngSha256='0'.repeat(64)));
  mutation('Reject missing rendered diagram',()=>edit(D+'math-assets-checks.json',d=>delete d.diagrams[Object.keys(d.diagrams)[0]]));
  mutation('Reject incorrect rendered formula count',()=>edit(D+'math-assets-checks.json',d=>d.mathExpressions++));
  mutation('Reject changed PDF bytes',()=>raw('public/ib-mock-solutions/physics-hl-set-c-paper-1.pdf',b=>Buffer.concat([b,Buffer.from('\nchanged')])));
  mutation('Reject incomplete final PDF visual coverage',()=>edit(D+'physics-pdf-review.json',d=>d.papers.pop()));
  mutation('Reject false all-pages visual declaration',()=>edit(D+'physics-pdf-review.json',d=>d.papers[0].allPagesInspected=false));
  mutation('Reject unresolved visual finding',()=>edit(D+'physics-pdf-review.json',d=>d.papers[0].findings=['Overlap found']));
  mutation('Reject failed visual group hidden by aggregate',()=>edit(D+'hl-c-pdf-review.json',d=>d.status='failed'));
  mutation('Reject missing visual group paper',()=>edit(D+'hl-c-pdf-review.json',d=>d.papers.pop()));
  mutation('Reject stale visual group hash',()=>edit(D+'hl-c-pdf-review.json',d=>d.papers[0].sha256='0'.repeat(64)));
  mutation('Reject visually reviewed wrong question hash',()=>edit(D+'physics-pdf-review.json',d=>d.papers[0].canonicalQuestionSha256='0'.repeat(64)));
  mutation('Reject solutions-first page ordering',()=>edit(D+'pdf-checks.json',d=>d.papers[0].solutionsStartPage=1));
  mutation('Reject unbound raster-to-PDF evidence',()=>edit(D+'pdf-checks.json',d=>d.papers[0].scientificAssetReportSha256='0'.repeat(64)));
  mutation('Reject changed rendered PDF hash',()=>edit(D+'pdf-render-checks.json',d=>d.records[0].sha256='0'.repeat(64)));
  mutation('Reject unapproved final render state',()=>edit(D+'pdf-render-checks.json',d=>d.status='rendered; review pending'));
  mutation('Reject retained QA database rows',()=>edit(D+'database-checks.json',d=>d.remainingQaRows=1));
  mutation('Reject disabled database RLS evidence',()=>edit(D+'database-checks.json',d=>d.rowLevelSecurityEnabled=false));
  mutation('Reject changed applied database migration',()=>raw(JSON.parse(readFileSync(join(fixture,D+'database-checks.json'))).migration.file,b=>Buffer.concat([b,Buffer.from('\n-- changed')])));
  mutation('Reject pending portal type checks',()=>edit(D+'portal-checks.json',d=>d.typeScript='pending'));
  mutation('Reject changed original source declaration',()=>edit(D+'source-provenance.json',d=>d.summary.allOriginalBytesUnchanged=false));
  mutation('Reject question-bank reuse evidence',()=>edit(D+'content-checks.json',d=>d.exactBankStemMatches=1));
  mutation('Reject frozen documentation mutation',()=>raw(D+'README.md',b=>Buffer.concat([b,Buffer.from('\nChanged after review.')])),()=>guard.verifyReviewManifest(fixture));
  mutation('Reject frozen review-script mutation',()=>raw('scripts/ib-physics-mocks-2026/independent_hl_c.py',b=>Buffer.concat([b,Buffer.from('\n# changed')])),()=>guard.verifyReviewManifest(fixture));
  mutation('Existing finalizer refuses silent rebaseline',()=>raw(D+'README.md',b=>Buffer.concat([b,Buffer.from('\nChanged after review.')])),()=>finalizer.finalizeReviewManifest(fixture));
  mutation('Reject omitted protected file entry',()=>edit(guard.MANIFEST,d=>d.files.pop()),()=>guard.verifyReviewManifest(fixture));
  mutation('Reject unexpected extra canonical paper',()=>{const f=C+'papers/physics-sl-set-c-paper-1.json';record(f);writeFileSync(join(fixture,f),'{}');});
  guard.verifyReviewManifest(fixture);
  const report={status:'passed',isolatedFixture:true,realReleaseManifestCreated:false,tests:results.length,rejectedMutations:results.length-1,baselineSummary:manifest.summary,results,harnessSha256:guard.sha256(readFileSync(fileURLToPath(import.meta.url))),harnessSource:readFileSync(fileURLToPath(import.meta.url),'utf8')};
  writeFileSync(join(repo,D+'review-guard-mutation-tests.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({status:'passed',tests:report.tests,rejectedMutations:report.rejectedMutations,fixture,realReleaseManifestCreated:false}));
} finally {assert.ok(resolve(fixture).startsWith(resolve(work)));rmSync(fixture,{recursive:true,force:true});}
